+import Yoga, {type Node as YogaNode} from 'yoga-layout';
+import {type DOMElement} from './dom.js';
+
+type Track = {
+	base: number;
+	fr: number;
+	auto: boolean;
+};
+
+type Placement = {start: number; end: number};
+
+const trackPattern = /minmax\\([^)]*\\)|\\S+/g;
+
+const parseTrack = (value: string): Track => {
+	if (value === 'auto') {
+		return {base: 0, fr: 0, auto: true};
+	}
+
+	const minmax = /^minmax\\(\\s*(\\d+(?:\\.\\d+)?)\\s*,\\s*(\\d+(?:\\.\\d+)?(?:fr)?)\\s*\\)$/.exec(value);
+	if (minmax) {
+		const minimum = Number(minmax[1]);
+		const maximum = minmax[2]!;
+		return {
+			base: minimum,
+			fr: maximum.endsWith('fr') ? Number(maximum.slice(0, -2)) || 1 : 0,
+			auto: false,
+		};
+	}
+
+	if (value.endsWith('fr')) {
+		return {base: 0, fr: Number(value.slice(0, -2)) || 1, auto: false};
+	}
+
+	const fixed = Number(value);
+	return {base: Number.isFinite(fixed) ? fixed : 0, fr: 0, auto: false};
+};
+
+const parseTracks = (template: string | undefined): Track[] =>
+	(template?.match(trackPattern) ?? ['auto']).map(parseTrack);
+
+const parsePlacement = (value: number | string | undefined): Placement | undefined => {
+	if (typeof value === 'number') {
+		return {start: value - 1, end: value};
+	}
+
+	if (!value) {
+		return;
+	}
+
+	const match = /^(\\d+)\\s*\\/\\s*(\\d+)$/.exec(value);
+	if (!match) {
+		return;
+	}
+
+	return {start: Number(match[1]) - 1, end: Number(match[2]) - 1};
+};
+
+const resolveTracks = (tracks: Track[], space: number, gap: number): number[] => {
+	const bases = tracks.map(track => track.base);
+	const totalFr = tracks.reduce((total, track) => total + track.fr, 0);
+	const remaining = Math.max(0, space - bases.reduce((a, b) => a + b, 0) - gap * (tracks.length - 1));
+	return bases.map((base, index) => base + (tracks[index]!.fr ? remaining * tracks[index]!.fr / totalFr : 0));
+};
+
+const trackOffset = (tracks: number[], index: number, gap: number): number =>
+	tracks.slice(0, index).reduce((total, size) => total + size, 0) + index * gap;
+
+const trackSpan = (tracks: number[], placement: Placement, gap: number): number =>
+	tracks.slice(placement.start, placement.end).reduce((total, size) => total + size, 0) + gap * (placement.end - placement.start - 1);
+
+const contentSize = (node: YogaNode, axis: 'width' | 'height'): number => {
+	const layout = node.getComputedLayout();
+	const start = axis === 'width' ? Yoga.EDGE_LEFT : Yoga.EDGE_TOP;
+	const end = axis === 'width' ? Yoga.EDGE_RIGHT : Yoga.EDGE_BOTTOM;
+	return Math.max(0, layout[axis] - node.getComputedPadding(start) - node.getComputedPadding(end) - node.getComputedBorder(start) - node.getComputedBorder(end));
+};
+
+const resetGeneratedGridStyles = (node: DOMElement): void => {
+	if (node.internal_gridItem && node.yogaNode) {
+		const yogaNode = node.yogaNode;
+		yogaNode.setPositionType(node.style.position === 'absolute' ? Yoga.POSITION_TYPE_ABSOLUTE : Yoga.POSITION_TYPE_RELATIVE);
+		yogaNode.setPosition(Yoga.EDGE_LEFT, node.style.left);
+		yogaNode.setPosition(Yoga.EDGE_RIGHT, node.style.right);
+		yogaNode.setPosition(Yoga.EDGE_TOP, node.style.top);
+		yogaNode.setPosition(Yoga.EDGE_BOTTOM, node.style.bottom);
+		if (typeof node.style.width === 'number') yogaNode.setWidth(node.style.width);
+		else yogaNode.setWidthAuto();
+		if (typeof node.style.height === 'number') yogaNode.setHeight(node.style.height);
+		else yogaNode.setHeightAuto();
+		node.internal_gridItem = false;
+	}
+
+	if (node.internal_gridHeight && node.yogaNode && node.style.height === undefined) {
+		node.yogaNode.setHeightAuto();
+		node.internal_gridHeight = false;
+	}
+
+	for (const child of node.childNodes) {
+		if (child.nodeName !== '#text') resetGeneratedGridStyles(child);
+	}
+};
+
+const gridChildren = (node: DOMElement): DOMElement[] =>
+	node.childNodes.filter((child): child is DOMElement => child.nodeName !== '#text' && Boolean(child.yogaNode));
+
+const applyGrid = (node: DOMElement): void => {
+	for (const child of gridChildren(node)) applyGrid(child);
+	if (node.style.display !== 'grid' || !node.yogaNode) return;
+
+	const children = gridChildren(node);
+	const columns = parseTracks(node.style.gridTemplateColumns);
+	const columnGap = node.style.columnGap ?? node.style.gap ?? 0;
+	const rowGap = node.style.rowGap ?? node.style.gap ?? 0;
+	const columnSizes = resolveTracks(columns, contentSize(node.yogaNode, 'width'), columnGap);
+	const placements: Array<{node: DOMElement; column: Placement; row: Placement}> = [];
+	const occupied = new Set<string>();
+	let nextRow = 0;
+	let nextColumn = 0;
+
+	for (const child of children) {
+		const column = parsePlacement(child.style.gridColumn);
+		const row = parsePlacement(child.style.gridRow);
+		let assignedColumn = column;
