+	const rows = parseTracks(node.style.gridTemplateRows);
+	while (rows.length < rowCount) rows.push({base: 0, fr: 0, auto: true});
+	const measuredRows = rows.map(track => track.base);
+	for (const item of placements) {
+		if (item.row.end - item.row.start !== 1 || !rows[item.row.start]!.auto || !item.node.yogaNode) continue;
+		measuredRows[item.row.start] = Math.max(measuredRows[item.row.start]!, item.node.yogaNode.getComputedLayout().height);
+	}
+	for (let index = 0; index < rows.length; index++) if (rows[index]!.auto) rows[index]!.base = measuredRows[index]!;
+	const rowSizes = resolveTracks(rows, contentSize(node.yogaNode, 'height'), rowGap);
+	const naturalHeight = rowSizes.reduce((total, size) => total + size, 0) + rowGap * (rowSizes.length - 1);
+	if (node.style.height === undefined) {
+		node.yogaNode.setHeight(naturalHeight + node.yogaNode.getComputedPadding(Yoga.EDGE_TOP) + node.yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM) + node.yogaNode.getComputedBorder(Yoga.EDGE_TOP) + node.yogaNode.getComputedBorder(Yoga.EDGE_BOTTOM));
+		node.internal_gridHeight = true;
+	}
+
+	for (const item of placements) {
+		const yogaNode = item.node.yogaNode!;
+		yogaNode.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		yogaNode.setPosition(Yoga.EDGE_LEFT, trackOffset(columnSizes, item.column.start, columnGap));
+		yogaNode.setPosition(Yoga.EDGE_TOP, trackOffset(rowSizes, item.row.start, rowGap));
+		yogaNode.setWidth(trackSpan(columnSizes, item.column, columnGap));
+		yogaNode.setHeight(trackSpan(rowSizes, item.row, rowGap));
+		item.node.internal_gridItem = true;
+	}
+};
+
+export const calculateLayout = (rootNode: DOMElement, width: number): void => {
+	resetGeneratedGridStyles(rootNode);
+	rootNode.yogaNode!.setWidth(width);
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+	applyGrid(rootNode);
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+	applyGrid(rootNode);
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+};
